using Router.Contracts.Plugins;

namespace Plugins.ModelRotator;

public sealed partial class ModelRotatorTerminal
{
    /// <summary>
    /// 构造模型轮转管理页面。页面只通过宿主注入的插件请求桥访问相对管理路由。
    /// </summary>
    private static PluginMainPage CreateMainPage()
        => new(
            "模型轮转",
            """
            <!doctype html>
            <html lang="zh-CN">
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width,initial-scale=1">
              <title>模型轮转</title>
              <style>
                :root{color-scheme:light dark;--bg:#f5f7fb;--panel:#fff;--ink:#17243b;--muted:#6e7b90;--line:#e3e8f0;--soft:#f4f6fa;--blue:#5269d8;--blue-soft:#eef1ff;--green:#17866f;--green-soft:#e8f6f1;--amber:#b66a08;--amber-soft:#fff4df;--red:#bc4652;--red-soft:#fff0f1;--shadow:0 12px 34px #17243b0d}
                @media(prefers-color-scheme:dark){:root{--bg:#11141a;--panel:#191e27;--ink:#e9edf5;--muted:#a0aabd;--line:#2b3340;--soft:#202631;--blue:#8494ff;--blue-soft:#252c49;--green:#55c9a4;--green-soft:#16372f;--amber:#f1b856;--amber-soft:#382c19;--red:#ff838c;--red-soft:#3b2228;--shadow:0 12px 34px #0004}}
                *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}button,input,select{font:inherit}button{cursor:pointer}.wrap{max-width:1240px;margin:auto;padding:24px 20px 48px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;flex-wrap:wrap;margin-bottom:18px}.eyebrow{color:var(--blue);font-size:11px;font-weight:800;letter-spacing:.12em}.top h1{font-size:24px;letter-spacing:-.03em;margin:2px 0 4px}.sub{color:var(--muted);margin:0;max-width:760px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);border-radius:9px;background:var(--panel);color:var(--ink);padding:8px 12px;font-weight:650;transition:.15s}.btn:hover{border-color:var(--blue);color:var(--blue)}.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff}.btn.soft{background:var(--blue-soft);border-color:transparent;color:var(--blue)}.btn.danger{color:var(--red);background:var(--red-soft);border-color:transparent}.btn.small{padding:5px 8px;font-size:12px}.btn:disabled{opacity:.55;cursor:wait}.banner{padding:11px 14px;border:1px solid var(--amber);border-radius:11px;background:var(--amber-soft);color:var(--ink);margin:12px 0}.banner[hidden]{display:none}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:15px 0}.stat{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:11px 14px;box-shadow:var(--shadow)}.stat span{display:block;color:var(--muted);font-size:12px}.stat strong{font-size:20px;font-variant-numeric:tabular-nums}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);overflow:hidden;margin-top:15px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 15px;border-bottom:1px solid var(--line)}.panel-head h2{font-size:15px;margin:0}.muted{color:var(--muted)}.count{color:var(--muted);font-size:12px;margin-left:6px} .table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:820px}th,td{text-align:left;padding:11px 13px;border-bottom:1px solid var(--line);vertical-align:top}th{background:var(--soft);font-size:12px;color:var(--muted);font-weight:700}tbody tr:last-child td{border-bottom:0}.name{font-weight:750;overflow-wrap:anywhere}.subline{font-size:11px;color:var(--muted);margin-top:3px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;overflow-wrap:anywhere}.tag,.chip{display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:999px;background:var(--soft);color:var(--muted);font-size:11px;max-width:100%;overflow-wrap:anywhere}.tag.on,.chip.active{background:var(--green-soft);color:var(--green)}.tag.off,.chip.down{background:var(--red-soft);color:var(--red)}.chip.warn{background:var(--amber-soft);color:var(--amber)}.chips{display:flex;flex-wrap:wrap;gap:6px}.target{display:flex;align-items:flex-start;gap:6px;margin:0 0 6px}.target:last-child{margin-bottom:0}.target-name{font-size:12px;overflow-wrap:anywhere;min-width:0}.target-meta{font-size:10px;color:var(--muted);display:block}.row-actions{display:flex;gap:3px;flex-wrap:wrap}.row-actions .btn{white-space:nowrap}.active-select{width:100%;max-width:230px;margin-top:7px}.empty,.state{padding:28px 15px;text-align:center;color:var(--muted)}.toolbar{display:flex;gap:8px;align-items:end;flex-wrap:wrap;padding:12px 15px}.field{display:flex;flex-direction:column;gap:5px;margin:0 0 13px;min-width:0}.field label{font-size:12px;font-weight:700;color:var(--muted)}.field input,.field select{width:100%;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);padding:9px 10px;min-height:38px}.field input:focus,.field select:focus{outline:2px solid color-mix(in srgb,var(--blue) 25%,transparent);border-color:var(--blue)}.field .hint{font-size:11px;color:var(--muted)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 13px}.field.full{grid-column:1/-1}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#10182899;display:flex;align-items:center;justify-content:center;padding:16px;overflow:auto}.modal-backdrop[hidden]{display:none}.modal{width:min(760px,100%);max-height:calc(100vh - 32px);overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:15px;box-shadow:0 24px 80px #0005}.modal.wide{width:min(960px,100%)}.modal-head{position:sticky;top:0;z-index:1;display:flex;justify-content:space-between;align-items:center;padding:13px 17px;background:var(--panel);border-bottom:1px solid var(--line)}.modal-head h2{font-size:16px;margin:0}.modal-body{padding:16px 17px}.modal-foot{display:flex;justify-content:flex-end;gap:8px;padding:12px 17px;border-top:1px solid var(--line)}.catalog{max-height:245px;overflow:auto;border:1px solid var(--line);border-radius:9px}.catalog-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;border-bottom:1px solid var(--line)}.catalog-row:last-child{border-bottom:0}.catalog-row span{overflow-wrap:anywhere}.picked{display:grid;gap:6px}.picked-row{display:flex;align-items:center;gap:7px;padding:7px 9px;border:1px solid var(--line);border-radius:8px}.picked-row .model{flex:1;overflow-wrap:anywhere}.probe-results{display:grid;gap:7px;margin:0;padding:0;list-style:none}.probe-results li{padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--soft);overflow-wrap:anywhere}.usage-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;padding:12px 15px}.usage-table{min-width:620px}.num{text-align:right;font-variant-numeric:tabular-nums}.notice{position:fixed;right:18px;bottom:18px;z-index:50;max-width:min(460px,calc(100vw - 36px));padding:11px 15px;border-radius:10px;background:#23314b;color:white;box-shadow:0 8px 24px #0003;display:none}.notice.error{background:#a53845}.notice.show{display:block}.footer-note{padding:0 15px 12px;font-size:11px;color:var(--muted)}
                @media(max-width:820px){.grid,.usage-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}body{font-size:13px}.wrap{padding:18px 13px 36px}}
                @media(max-width:560px){.top{flex-direction:column}.actions{width:100%}.actions .btn{flex:1}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.modal-backdrop{padding:8px}.modal{max-height:calc(100vh - 16px)}.panel-head{align-items:flex-start}.grid,.usage-kpis{gap:7px}.stat{padding:9px 10px}.stat strong{font-size:17px}.modal-body{padding:13px}.modal-foot{padding:10px 13px}}
              </style>
            </head>
            <body>
              <main class="wrap">
                <header class="top">
                  <div><div class="eyebrow">MODEL ROTATOR · ADMIN</div><h1>模型轮转</h1><p class="sub">每个虚拟模型按优先级绑定实际平台模型。请求使用当前活跃目标，失败达到阈值后再切换；可查看目标健康状态、手动固定活跃模型并统计真实模型 Token 用量。</p></div>
                  <div class="actions"><button class="btn" id="refresh" type="button">刷新</button><button class="btn soft" id="probe" type="button">立即探测</button><button class="btn" id="settingsOpen" type="button">平台设置</button><button class="btn primary" id="newRoute" type="button">＋ 新建虚拟模型</button></div>
                </header>
                <div id="baseNotice" class="banner" role="status" hidden></div>
                <div class="grid" aria-label="模型轮转摘要"><div class="stat"><span>虚拟模型</span><strong id="statRoutes">—</strong></div><div class="stat"><span>已启用</span><strong id="statEnabled">—</strong></div><div class="stat"><span>实际目标</span><strong id="statTargets">—</strong></div><div class="stat"><span>异常目标</span><strong id="statDown">—</strong></div></div>
                <section class="panel" aria-labelledby="routesTitle"><div class="panel-head"><h2 id="routesTitle">虚拟模型路由<span id="routeCount" class="count">0 个</span></h2><span class="muted" id="routeState" role="status" aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th>虚拟模型</th><th>状态</th><th>当前活跃</th><th>实际模型（按优先级）</th><th>失败阈值</th><th>操作</th></tr></thead><tbody id="routeRows"></tbody></table></div><div id="routeEmpty" class="empty" hidden>还没有虚拟模型。请新建虚拟模型并选择一个或多个实际模型。</div></section>
                <section class="panel" aria-labelledby="usageTitle"><div class="panel-head"><h2 id="usageTitle">真实模型 Token 用量</h2><button class="btn small" id="usageRefresh" type="button">刷新统计</button></div><div class="toolbar"><div class="field" style="min-width:170px"><label for="usageRange">时间范围</label><select id="usageRange"><option value="24h">最近 24 小时</option><option value="7d" selected>最近 7 天</option><option value="30d">最近 30 天</option><option value="custom">自定义日期</option></select></div><div class="field" id="fromWrap" hidden><label for="usageFrom">开始日期</label><input id="usageFrom" type="date"></div><div class="field" id="toWrap" hidden><label for="usageTo">结束日期（含当天）</label><input id="usageTo" type="date"></div></div><div id="usageStatus" class="state" role="status" aria-live="polite">正在加载 Token 统计…</div><div id="usageContent" hidden><div class="usage-kpis"><div class="stat"><span>总 Token</span><strong id="usageTotal">0</strong></div><div class="stat"><span>输入 Token</span><strong id="usagePrompt">0</strong></div><div class="stat"><span>输出 Token</span><strong id="usageCompletion">0</strong></div><div class="stat"><span>成功请求</span><strong id="usageRequests">0</strong></div></div><div class="table-wrap"><table class="usage-table"><thead><tr><th>真实模型</th><th class="num">请求</th><th class="num">输入 Token</th><th class="num">输出 Token</th><th class="num">总 Token</th></tr></thead><tbody id="usageRows"></tbody></table></div><div id="usageCaption" class="footer-note"></div></div></section>
              </main>
              <section id="editLayer" class="modal-backdrop" hidden><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="editTitle"><header class="modal-head"><h2 id="editTitle">新建虚拟模型</h2><button class="btn small" type="button" data-close="editLayer" aria-label="关闭编辑">关闭</button></header><div class="modal-body"><div class="form-grid"><div class="field"><label for="virtualName">虚拟模型名称</label><input id="virtualName" type="text" autocomplete="off" placeholder="例如 gpt-4o-fast"><span class="hint">这是提供给客户端调用的模型名称。</span></div><div class="field"><label for="failureThreshold">连续失败阈值</label><input id="failureThreshold" type="number" min="1" max="100" value="3"><span class="hint">达到阈值后禁用当前目标并切换到下一个健康目标。</span></div><div class="field"><label for="virtualEnabled">模型状态</label><select id="virtualEnabled"><option value="true">启用</option><option value="false">停用</option></select></div><div class="field"><label for="probeEndpoint">探测端点</label><select id="probeEndpoint"><option value="/v1/chat/completions">/v1/chat/completions</option><option value="/v1/completions">/v1/completions</option><option value="/v1/embeddings">/v1/embeddings</option><option value="/v1/responses">/v1/responses</option><option value="/v1/messages">/v1/messages</option></select><span class="hint">Embedding 等非对话模型请选择对应端点。</span></div></div><div class="field"><label for="catalogSearch">平台实际模型目录</label><div class="actions"><input id="catalogSearch" type="search" placeholder="搜索模型…" autocomplete="off" aria-label="搜索平台模型" style="flex:1;min-width:180px"><button id="catalogRefresh" class="btn small" type="button">重新读取目录</button></div><span id="catalogStatus" class="hint" role="status" aria-live="polite">打开编辑器时读取平台模型目录。</span><button id="catalogSettings" class="btn small" type="button" hidden>去设置里填密钥</button></div><div id="catalog" class="catalog" aria-label="可选实际模型"></div><div class="field" style="margin-top:14px"><label>已选实际模型 · 按钮调整优先级</label><div id="picked" class="picked"></div><span class="hint">顺序即优先级。保存顺序改变后，原活跃 pin 会清除，下次请求按新优先级选择。</span></div></div><footer class="modal-foot"><button class="btn" type="button" data-close="editLayer">取消</button><button id="saveRoute" class="btn primary" type="button">保存虚拟模型</button></footer></div></section>
              <section id="settingsLayer" class="modal-backdrop" hidden><div class="modal" role="dialog" aria-modal="true" aria-labelledby="settingsTitle"><header class="modal-head"><h2 id="settingsTitle">平台设置</h2><button class="btn small" type="button" data-close="settingsLayer" aria-label="关闭设置">关闭</button></header><div class="modal-body"><div class="field"><label for="baseUrl">平台回环地址</label><input id="baseUrl" type="url" placeholder="http://127.0.0.1:8080" autocomplete="url"><span class="hint">插件将实际请求转发到该平台地址。与平台同机时通常使用本机回环地址。</span></div><div class="field"><label for="apiKey">平台 API Key</label><input id="apiKey" type="password" autocomplete="new-password" placeholder="留空保持现有密钥"><span class="hint" id="apiKeyHint">回环请求走 <code>/v1</code>，宿主会校验下游密钥：这里必须填 Router2API 自己的 API 密钥（管理后台「密钥管理」），否则读取目录和转发请求都会返回 401。不会回显完整密钥；输入新值即可替换。</span></div><label class="hint" style="display:flex;align-items:center;gap:8px;margin:-3px 0 14px"><input id="clearApiKey" type="checkbox"> 清除已保存的平台 API Key</label><div class="form-grid"><div class="field"><label for="firstWait">单个模型首字节等待（秒）</label><input id="firstWait" type="number" min="10" max="300" value="30"><span class="hint">一个模型等待响应头的上限。</span></div><div class="field"><label for="firstBudget">首字节总预算（秒）</label><input id="firstBudget" type="number" min="10" max="600" value="180"><span class="hint">所有候选模型合计等待上限。</span></div><div class="field"><label for="streamIdle">流式空闲超时（秒）</label><input id="streamIdle" type="number" min="5" max="600" value="30"><span class="hint">已开始的流连续无数据达到此值后视为中断。</span></div><div class="field"><label for="probeInterval">后台探测间隔（分钟）</label><input id="probeInterval" type="number" min="1" max="60" value="5"><span class="hint">定时探测被禁用的实际模型。</span></div><div class="field"><label for="probeTimeout">单目标探测超时（秒）</label><input id="probeTimeout" type="number" min="5" max="180" value="45"><span class="hint">默认 45 秒。免费上游拥塞时单个目标十几秒无响应很常见，设得太短会把慢但可用的目标判成异常。</span></div><div class="field full"><label for="activationPolicy">活跃位切换策略</label><select id="activationPolicy"><option value="sticky">sticky：连续失败达到阈值后切换</option><option value="prefer-highest">prefer-highest：成功后回到最高优先级</option></select><span class="hint">sticky 可避免高优先级模型短暂抖动后频繁抢回；prefer-highest 恢复后会优先使用高优先级目标。</span></div></div></div><footer class="modal-foot"><button class="btn" type="button" data-close="settingsLayer">取消</button><button id="saveSettings" class="btn primary" type="button">保存设置</button></footer></div></section>
              <section id="probeLayer" class="modal-backdrop" hidden><div class="modal" role="dialog" aria-modal="true" aria-labelledby="probeTitle"><header class="modal-head"><h2 id="probeTitle">模型探测结果</h2><button class="btn small" type="button" data-close="probeLayer">关闭</button></header><div class="modal-body"><div id="probeSummary" role="status" aria-live="polite" class="banner"></div><ul id="probeResults" class="probe-results"></ul></div><footer class="modal-foot"><button class="btn" type="button" data-close="probeLayer">关闭</button></footer></div></section>
              <div id="notice" class="notice" role="status" aria-live="polite"></div>
              <script>
                (()=>{
                  'use strict';
                  const $=id=>document.getElementById(id);
                  const state={virtuals:[],settings:{},catalog:[],picked:[],editing:null,noticeTimer:0};
                  const api=(method,route,body)=>window.Router2API.request(method,route,body===undefined?null:body);
                  const node=(tag,cls,text)=>{const element=document.createElement(tag);if(cls)element.className=cls;if(text!==undefined)element.textContent=String(text);return element};
                  const button=(text,cls,action,label)=>{const element=node('button','btn '+(cls||''),text);element.type='button';if(action)element.dataset.action=action;if(label)element.setAttribute('aria-label',label);return element};
                  function toast(message,error=false){const el=$('notice');el.textContent=String(message||'请求失败');el.classList.toggle('error',error);el.classList.add('show');clearTimeout(state.noticeTimer);state.noticeTimer=setTimeout(()=>el.classList.remove('show'),5000)}
                  function errorText(error){return error&&error.message?error.message:String(error||'未知错误')}
                  function number(value){const parsed=Number(value);return Number.isFinite(parsed)&&parsed>=0?parsed:0}
                  function formatNumber(value){return number(value).toLocaleString('zh-CN',{maximumFractionDigits:0})}
                  function dateLocal(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return y+'-'+m+'-'+d}
                  function selectedRange(){const mode=$('usageRange').value,now=new Date();if(mode==='custom'){const from=$('usageFrom').value,to=$('usageTo').value;if(!from||!to)throw Error('请选择开始和结束日期');const start=new Date(from+'T00:00:00'),end=new Date(to+'T00:00:00');if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||start>end)throw Error('日期范围无效：开始日期不能晚于结束日期');end.setDate(end.getDate()+1);return{from:start.toISOString(),to:end.toISOString()}}const ms=mode==='24h'?86400000:mode==='30d'?30*86400000:7*86400000;return{from:new Date(now.getTime()-ms).toISOString(),to:now.toISOString()}}
                  function addCell(row,content,cls){const cell=node('td',cls||'');if(content instanceof Node)cell.append(content);else cell.textContent=content===undefined?'':String(content);row.append(cell);return cell}
                  function targetChip(target,threshold){const chip=node('span','chip '+(target.disabled?'down':target.isActive?'active':(number(target.failures)||number(target.timeouts))?'warn':''));const label=node('span','target-name',target.model);const details=[];details.push(target.disabled?'已禁用':target.isActive?'当前使用':'待命');details.push('连续失败 '+number(target.failures)+'/'+number(threshold));if(number(target.timeouts))details.push('超时 '+number(target.timeouts));if(number(target.firstByteMs))details.push('首字 '+(Math.round(number(target.firstByteMs)/100)/10)+'s / 等 '+number(target.waitSeconds)+'s');label.append(node('span','target-meta',details.join(' · ')));chip.append(label);return chip}
                  function render(){const rows=$('routeRows');rows.replaceChildren();let enabled=0,targets=0,down=0;for(const route of state.virtuals){if(route.enabled)enabled++;const list=Array.isArray(route.targets)?route.targets:[];targets+=list.length;down+=list.filter(item=>item.disabled).length;const row=document.createElement('tr');const title=node('div','name',route.virtualModel);const callModel=route.callModel||route.virtualModel;const info=node('div','subline',(list.length||0)+' 个实际模型 · 探测 '+(route.probeEndpoint||'/v1/chat/completions'));const call=node('div','subline mono','下游调用：'+callModel);const titleWrap=node('div');titleWrap.append(title,info,call);if(Array.isArray(route.bareTargets)&&route.bareTargets.length)titleWrap.append(node('span','chip warn',route.bareTargets.length+' 个目标缺 platform/ 前缀'));addCell(row,titleWrap);const status=node('span','tag '+(route.enabled?'on':'off'),route.enabled?'启用':'停用');addCell(row,status);const activeCell=document.createElement('td');const active=list.find(item=>item.isActive||item.model===route.activeModel);activeCell.append(active?targetChip({...active,isActive:true},route.failureThreshold):node('span','muted',list.some(item=>item.disabled)?'当前没有健康目标':'尚未选择活跃模型'));const select=document.createElement('select');select.className='active-select';select.setAttribute('aria-label','手动切换 '+route.virtualModel+' 的活跃实际模型');const auto=document.createElement('option');auto.value='';auto.textContent='自动按优先级选择';select.append(auto);for(const item of list){const option=document.createElement('option');option.value=item.model;option.textContent=item.model+(item.disabled?'（已禁用，选择可解除）':'');if(item.isActive||item.model===route.activeModel)option.selected=true;select.append(option)}const activate=button('应用切换','small soft','activate');activate.dataset.name=route.virtualModel;activeCell.append(select,activate);row.append(activeCell);const targetsCell=document.createElement('td');const chips=node('div','chips');for(const item of list)chips.append(targetChip(item,route.failureThreshold));if(!list.length)chips.append(node('span','muted','无实际模型'));targetsCell.append(chips);row.append(targetsCell);addCell(row,route.failureThreshold||3);const actions=node('div','row-actions');const edit=button('编辑','small','edit');edit.dataset.name=route.virtualModel;const toggle=button(route.enabled?'停用':'启用','small','toggle');toggle.dataset.name=route.virtualModel;const remove=button('删除','small danger','delete');remove.dataset.name=route.virtualModel;actions.append(edit,toggle,remove);addCell(row,actions);rows.append(row)}$('routeCount').textContent=state.virtuals.length+' 个';$('statRoutes').textContent=state.virtuals.length;$('statEnabled').textContent=enabled;$('statTargets').textContent=targets;$('statDown').textContent=down;$('routeEmpty').hidden=state.virtuals.length>0;$('baseNotice').hidden=Boolean(state.settings.baseUrl);$('baseNotice').textContent=state.settings.baseUrl?'':'尚未配置平台回环地址，平台模型目录和虚拟模型转发暂不可用。请打开「平台设置」填写地址。';$('routeState').textContent='已加载';}
                  async function load(){ $('routeState').textContent='正在读取…';try{const [virtualPayload,settings]=await Promise.all([api('GET','virtual'),api('GET','settings')]);state.virtuals=Array.isArray(virtualPayload?.virtuals)?virtualPayload.virtuals:[];state.settings=settings||{};render()}catch(error){$('routeState').textContent='读取失败：'+errorText(error);toast('页面数据加载失败：'+errorText(error),true)}}
                  function openEdit(name){const route=state.virtuals.find(item=>item.virtualModel===name)||null;state.editing=route;state.picked=route&&Array.isArray(route.targets)?route.targets.map(item=>typeof item==='string'?item:item.model).filter(Boolean):[];$('editTitle').textContent=route?'编辑虚拟模型':'新建虚拟模型';$('virtualName').value=route?.virtualModel||'';$('virtualName').readOnly=Boolean(route);$('failureThreshold').value=route?.failureThreshold||3;$('virtualEnabled').value=route?.enabled===false?'false':'true';$('probeEndpoint').value=route?.probeEndpoint||'/v1/chat/completions';$('catalogSearch').value='';$('catalog').replaceChildren();$('catalogSettings').hidden=true;$('catalogStatus').textContent='正在读取平台模型目录…';$('editLayer').hidden=false;renderPicked();loadCatalog().catch(error=>{$('catalogStatus').textContent='模型目录读取失败：'+errorText(error);toast(errorText(error),true)})}
                  async function loadCatalog(){const payload=await api('GET','platform/models');state.catalog=(Array.isArray(payload?.models)?payload.models:[]).map(item=>typeof item==='string'?{id:item,name:item,platform:''}:{id:String(item?.id||''),name:String(item?.name||item?.id||''),platform:String(item?.platform||'')}).filter(item=>item.id);$('catalogStatus').textContent=state.catalog.length?'共 '+state.catalog.length+' 个平台模型':String(payload?.detail||'没有读到模型目录：请检查回环地址与 API Key');$('catalogSettings').hidden=state.catalog.length>0;renderCatalog()}
                  function renderCatalog(){const box=$('catalog'),query=$('catalogSearch').value.trim().toLowerCase();box.replaceChildren();const list=state.catalog.filter(item=>!query||(item.id+' '+item.name+' '+item.platform).toLowerCase().includes(query));if(!list.length){box.append(node('div','empty',state.catalog.length?'没有匹配模型':'请先读取平台模型目录'));return}for(const model of list){const row=node('div','catalog-row');const text=node('span','',model.name+(model.platform?' · '+model.platform:''));const add=button(state.picked.includes(model.id)?'已添加':'加入','small '+(state.picked.includes(model.id)?'soft':''),'pick');add.dataset.model=model.id;add.disabled=state.picked.includes(model.id);row.append(text,add);box.append(row)}}
                  function renderPicked(){const box=$('picked');box.replaceChildren();if(!state.picked.length){box.append(node('div','empty','请从上方模型目录加入实际模型'));return}state.picked.forEach((model,index)=>{const row=node('div','picked-row');row.append(node('span','tag',String(index+1)),node('span','model',model));const up=button('上移','small','move-up','将 '+model+' 上移');up.dataset.index=index;up.disabled=index===0;const down=button('下移','small','move-down','将 '+model+' 下移');down.dataset.index=index;down.disabled=index===state.picked.length-1;const remove=button('移除','small danger','remove-model','移除 '+model);remove.dataset.index=index;row.append(up,down,remove);box.append(row)})}
                  async function saveRoute(){const name=$('virtualName').value.trim();if(!name){toast('请填写虚拟模型名称',true);$('virtualName').focus();return}if(!state.picked.length){toast('请至少选择一个实际模型',true);return}const buttonEl=$('saveRoute');buttonEl.disabled=true;try{await api('POST','virtual/save',{virtualModel:name,targets:state.picked,failureThreshold:Number($('failureThreshold').value)||3,enabled:$('virtualEnabled').value==='true',probeEndpoint:$('probeEndpoint').value});$('editLayer').hidden=true;toast('虚拟模型已保存');await load()}catch(error){toast('保存失败：'+errorText(error),true)}finally{buttonEl.disabled=false}}
                  function openSettings(){const settings=state.settings||{};$('baseUrl').value=settings.baseUrl||'http://127.0.0.1:8080';$('apiKey').value='';$('apiKey').placeholder=settings.hasApiKey?'已保存 '+(settings.apiKeyMasked||'密钥')+'；留空不修改':'未配置密钥，可留空';$('apiKeyHint').textContent=settings.hasApiKey?'当前回环密钥：'+(settings.apiKey||settings.apiKeyMasked||'已保存')+'（即 Router2API 自己的 API 密钥）；输入新密钥替换或勾选清除。':'未配置平台 API Key：读取目录与转发请求都会被宿主判为 401。';$('clearApiKey').checked=false;$('firstWait').value=settings.firstWaitSeconds||30;$('firstBudget').value=settings.firstByteBudgetSeconds||180;$('streamIdle').value=settings.streamIdleSeconds||30;$('probeInterval').value=settings.probeIntervalMinutes||5;$('probeTimeout').value=settings.probeTimeoutSeconds||45;$('activationPolicy').value=settings.activationPolicy==='prefer-highest'?'prefer-highest':'sticky';$('settingsLayer').hidden=false}
                  async function saveSettings(){const body={baseUrl:$('baseUrl').value.trim(),firstWaitSeconds:Number($('firstWait').value),firstByteBudgetSeconds:Number($('firstBudget').value),streamIdleSeconds:Number($('streamIdle').value),probeIntervalMinutes:Number($('probeInterval').value),probeTimeoutSeconds:Number($('probeTimeout').value),activationPolicy:$('activationPolicy').value};const key=$('apiKey').value.trim();if(key)body.apiKey=key;if($('clearApiKey').checked)body.clearApiKey=true;const save=$('saveSettings');save.disabled=true;try{await api('POST','settings/save',body);$('settingsLayer').hidden=true;toast('平台设置已保存');await load()}catch(error){toast('设置保存失败：'+errorText(error),true)}finally{save.disabled=false}}
                  function showUsage(payload){const totals=payload?.totalsOverall||{};$('usageTotal').textContent=formatNumber(totals.totalTokens);$('usagePrompt').textContent=formatNumber(totals.promptTokens);$('usageCompletion').textContent=formatNumber(totals.completionTokens);$('usageRequests').textContent=formatNumber(totals.requests);const rows=$('usageRows');rows.replaceChildren();const models=Array.isArray(payload?.totals)?payload.totals:[];for(const item of models){const row=document.createElement('tr');addCell(row,item.model||'未知模型','name');addCell(row,formatNumber(item.requests),'num');addCell(row,formatNumber(item.promptTokens),'num');addCell(row,formatNumber(item.completionTokens),'num');addCell(row,formatNumber(item.totalTokens),'num');rows.append(row)}$('usageStatus').hidden=models.length>0;$('usageContent').hidden=models.length===0;if(!models.length){$('usageStatus').textContent='此时间范围没有成功请求记录。';return}const from=payload.from?new Date(payload.from).toLocaleString('zh-CN'):'';const to=payload.to?new Date(payload.to).toLocaleString('zh-CN'):'';$('usageCaption').textContent='时间范围：'+from+' 至 '+to+'。请求数按成功请求计；Token 取自上游返回的 usage（流式响应在流末尾补记），缺少 usage 时不估算，只计请求数。'+(payload.truncated?' 统计可能因容量上限不完整。':' 保留最近 '+(payload.retentionDays||31)+' 天。')}
                  let usageRequest=0;async function loadUsage(){const request=++usageRequest;$('usageStatus').hidden=false;$('usageStatus').className='state';$('usageStatus').textContent='正在加载 Token 统计…';$('usageContent').hidden=true;try{const range=selectedRange(),query=new URLSearchParams({from:range.from,to:range.to});const payload=await api('GET','usage/stats?'+query.toString());if(request!==usageRequest)return;showUsage(payload||{})}catch(error){if(request!==usageRequest)return;$('usageStatus').hidden=false;$('usageStatus').className='state';$('usageStatus').textContent='Token 统计加载失败：'+errorText(error);toast(errorText(error),true)}}
                  function displayProbe(payload){const results=Array.isArray(payload?.results)?payload.results:[];$('probeSummary').textContent='探测完成：共 '+number(payload?.total)+' 个，正常 '+number(payload?.healthy)+'，异常 '+number(payload?.failed)+'，超时 '+number(payload?.timeout)+'，恢复 '+number(payload?.recovered)+(number(payload?.inconclusive)?'；'+number(payload.inconclusive)+' 个仅返回空内容，无法证明可用':'')+(number(payload?.remaining)?'；还有 '+number(payload.remaining)+' 个未探测，可再次点击继续':'');const list=$('probeResults');list.replaceChildren();if(!results.length)list.append(node('li','muted','本轮没有可展示的探测结果。'));for(const item of results){const status=item.timedOut?'超时':item.ok?(item.inconclusive?'结果不确定（空响应）':'正常'):'异常';const detail=[item.virtualModel,item.model,status,item.status?'HTTP '+item.status:'',item.elapsedMs?Math.round(item.elapsedMs)+' ms':'',item.message||''].filter(Boolean).join(' · ');list.append(node('li',item.timedOut?'chip warn':(item.ok?(item.inconclusive?'chip warn':'chip active'):'chip down'),detail))}$('probeLayer').hidden=false}
                  async function runProbe(){const btn=$('probe');btn.disabled=true;btn.textContent='探测中…';try{const payload=await api('POST','probe/run',{});displayProbe(payload||{});await load()}catch(error){toast('探测失败：'+errorText(error),true)}finally{btn.disabled=false;btn.textContent='立即探测'}}
                  document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){$(close.dataset.close).hidden=true;return}const actionButton=event.target.closest('[data-action]');if(!actionButton)return;const action=actionButton.dataset.action;try{if(action==='pick'){if(!state.picked.includes(actionButton.dataset.model))state.picked.push(actionButton.dataset.model);renderPicked();renderCatalog()}else if(action==='move-up'||action==='move-down'){const index=Number(actionButton.dataset.index),to=action==='move-up'?index-1:index+1;if(to>=0&&to<state.picked.length){[state.picked[index],state.picked[to]]=[state.picked[to],state.picked[index]];renderPicked();renderCatalog()}}else if(action==='remove-model'){state.picked.splice(Number(actionButton.dataset.index),1);renderPicked();renderCatalog()}else{const name=actionButton.dataset.name;const route=state.virtuals.find(item=>item.virtualModel===name);if(action==='edit')openEdit(name);else if(action==='toggle'){await api('POST','virtual/toggle',{virtualModel:name,enabled:!route?.enabled});toast('虚拟模型状态已更新');await load()}else if(action==='delete'){if(actionButton.dataset.confirm!=='1'){actionButton.dataset.confirm='1';actionButton.textContent='再次点击确认';setTimeout(()=>{if(actionButton.isConnected){delete actionButton.dataset.confirm;actionButton.textContent='删除'}},4000);return}await api('POST','virtual/delete',{virtualModel:name});toast('已删除 '+name);await load()}else if(action==='activate'){const model=actionButton.closest('td').querySelector('select').value;await api('POST','virtual/activate',{virtualModel:name,model});toast(model?'已手动切换活跃目标：'+model+'（从下次请求开始生效，进行中的连接不受影响）':'已恢复自动按优先级选择');await load()}}}catch(error){toast(errorText(error),true)}});
                  $('refresh').addEventListener('click',async()=>{const btn=$('refresh');btn.disabled=true;try{await load();await loadUsage()}finally{btn.disabled=false}});$('newRoute').addEventListener('click',()=>openEdit(null));$('saveRoute').addEventListener('click',saveRoute);$('catalogSearch').addEventListener('input',renderCatalog);$('catalogRefresh').addEventListener('click',()=>loadCatalog().catch(error=>{$('catalogSettings').hidden=false;toast('目录读取失败：'+errorText(error),true)}));$('catalogSettings').addEventListener('click',openSettings);$('settingsOpen').addEventListener('click',openSettings);$('saveSettings').addEventListener('click',saveSettings);$('probe').addEventListener('click',runProbe);$('usageRefresh').addEventListener('click',loadUsage);$('usageRange').addEventListener('change',()=>{const custom=$('usageRange').value==='custom';$('fromWrap').hidden=!custom;$('toWrap').hidden=!custom;if(custom){const today=new Date();$('usageTo').value=$('usageTo').value||dateLocal(today);const week=new Date(today.getTime()-7*86400000);$('usageFrom').value=$('usageFrom').value||dateLocal(week);return}loadUsage()});$('usageFrom').addEventListener('change',loadUsage);$('usageTo').addEventListener('change',loadUsage);document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.modal-backdrop:not([hidden])').forEach(layer=>layer.hidden=true)});
                  load();loadUsage();
                })();
              </script>
